<template><main class="hh-page surgery-detail"><router-link to="/unidad-quirurgica/agenda" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a agenda</router-link><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="error&&!surgery" class="alert alert-danger">{{error}}</div><template v-else-if="surgery"><section class="detail-hero"><span><i class="ph ph-first-aid-kit"></i></span><div><small>PROCEDIMIENTO #{{surgery.id}}</small><h1>{{surgery.servicio||'Cirugía programada'}}</h1><p>{{surgery.paciente}} · {{surgery.identificacion}}</p></div><div class="state"><small>{{surgery.estado_programacion}}</small><strong>{{surgery.estado_procedimiento}}</strong></div></section><div v-if="notice" class="alert alert-success mt-3">{{notice}}</div><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><section class="summary mt-4"><article><small>Quirófano</small><strong>{{surgery.nombre_quirofano}}</strong></article><article><small>Fecha y horario</small><strong>{{surgery.fecha}} · {{surgery.hora_inicio}}–{{surgery.hora_fin}}</strong></article><article><small>Cirujano</small><strong>{{surgery.cirujano}}</strong></article><article><small>Orden de servicio</small><strong>#{{surgery.id_orden_de_servicio||'—'}}</strong></article></section><div class="detail-grid mt-4"><section><header><h2>Equipo médico</h2><span>{{surgery.equipo?.length||0}}</span></header><div class="team"><article v-for="item in surgery.equipo||[]" :key="item.id_perfil"><span><i class="ph ph-user-circle"></i></span><div><small>{{item.perfil}}</small><strong>{{item.profesional||item.nombre_profesional||'Pendiente de asignar'}}</strong></div><i :class="item.id_profesional?'ph ph-check-circle text-success':'ph ph-warning text-warning'"></i></article></div></section><section><header><h2>Reservas y recursos</h2></header><div class="resource"><small>Reserva de cama</small><strong>{{surgery.reserva?.estado||surgery.reserva?'Registrada':'Sin reserva'}}</strong></div><div class="resource"><small>Despachos de almacén</small><strong>{{surgery.despachos?.length||0}} relacionados</strong></div></section></div><section class="operations mt-4"><div><small>ACCIONES OPERATIVAS</small><h2>Gestión del procedimiento</h2><p>El backend validará horario, equipo y reservas antes de aplicar el cambio.</p></div><div><button class="btn btn-success" @click="openAction('start')"><i class="ph ph-play me-1"></i>Iniciar</button><button class="btn btn-primary" @click="openAction('finish')"><i class="ph ph-check me-1"></i>Finalizar</button><button class="btn btn-outline-danger" @click="openAction('cancel')"><i class="ph ph-x me-1"></i>Anular</button></div></section><Teleport to="body"><div v-if="action" class="modal-layer" @mousedown.self="close"><section class="action-modal"><header><div><small>ACCIÓN QUIRÚRGICA</small><h3>{{titles[action]}}</h3></div><button class="btn-close" :disabled="saving" @click="close"></button></header><form @submit.prevent="execute"><div class="modal-body"><p>Procedimiento: <strong>{{surgery.servicio}}</strong></p><label class="form-label">{{action==='cancel'?'Motivo':'Observaciones'}} *</label><textarea v-model.trim="observation" maxlength="255" rows="3" class="form-control" required></textarea><template v-if="action==='finish'&&surgery.reserva"><label class="form-label mt-3">ID de reserva *</label><input v-model.number="reservationId" type="number" class="form-control" required></template></div><footer><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="close">Cancelar</button><button class="btn" :class="action==='cancel'?'btn-danger':action==='start'?'btn-success':'btn-primary'" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-2"></span>Confirmar</button></footer></form></section></div></Teleport></template></main></template>
<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{anularCirugia,cerrarCirugia,consultarDetalleCirugia,iniciarCirugia}from'@/services/unidadQuirurgica';const route=useRoute(),surgery=ref(null),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),action=ref(null),observation=ref(''),reservationId=ref(''),titles={start:'Iniciar cirugía',finish:'Finalizar cirugía',cancel:'Anular cirugía'};async function load(){loading.value=true;error.value='';try{const r=await consultarDetalleCirugia(route.params.id);surgery.value=r?.data||r}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}function openAction(v){error.value='';notice.value='';action.value=v;observation.value='';reservationId.value=surgery.value.reserva?.id||''}function close(){if(!saving.value)action.value=null}async function execute(){saving.value=true;error.value='';try{if(action.value==='start')await iniciarCirugia(surgery.value.id,observation.value);if(action.value==='cancel')await anularCirugia(surgery.value.id,observation.value);if(action.value==='finish')await cerrarCirugia(surgery.value.id,{observaciones:observation.value,...(reservationId.value?{reserva_id:Number(reservationId.value),id_orden_de_servicio:Number(surgery.value.id_orden_de_servicio)}:{})});action.value=null;notice.value='Procedimiento actualizado correctamente.';await load()}catch(e){error.value=obtenerMensajeError(e);action.value=null}finally{saving.value=false}}onMounted(load)</script>
<style scoped>.detail-hero{display:flex;align-items:center;gap:.8rem;padding:1.3rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#124b76,#1187ac);color:#fff}.detail-hero>span{display:grid;place-items:center;width:50px;height:50px;border-radius:14px;background:#ffffff22;font-size:1.3rem}.detail-hero>div:nth-child(2){flex:1}.detail-hero small{font-size:.68rem}.detail-hero h1{margin:.1rem 0;font-size:1.35rem}.detail-hero p{margin:0;opacity:.8}.state{text-align:right}.state small,.state strong{display:block}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem}.summary article,.detail-grid>section,.operations{padding:1rem;border:1px solid #dfe7ee;border-radius:.8rem;background:#fff}.summary small,.summary strong{display:block}.summary small{color:#8090a0}.detail-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:.8rem}.detail-grid section>header{display:flex;justify-content:space-between;border-bottom:1px solid #e6ebef;padding-bottom:.6rem}.detail-grid h2,.operations h2{font-size:1rem}.team{display:grid}.team article{display:flex;align-items:center;gap:.6rem;padding:.6rem;border-bottom:1px solid #edf0f2}.team article>span{font-size:1.3rem;color:var(--bs-primary)}.team article>div{flex:1}.team small,.team strong{display:block}.resource{padding:.7rem;border-bottom:1px solid #edf0f2}.resource small,.resource strong{display:block}.operations{display:flex;align-items:center;justify-content:space-between}.operations small{color:var(--bs-primary);font-weight:800}.operations p{margin:0;color:#738294}.operations>div:last-child{display:flex;gap:.5rem}.modal-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;padding:1rem;background:#071522b8}.action-modal{width:min(500px,100%);border-radius:1rem;background:#fff}.action-modal>header{display:flex;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ef}.action-modal h3{font-size:1rem}.action-modal .modal-body{padding:1.2rem}.action-modal footer{display:flex;justify-content:flex-end;gap:.5rem;padding:1rem 1.2rem;border-top:1px solid #e3e9ef}@media(max-width:800px){.summary{grid-template-columns:repeat(2,1fr)}.detail-grid{grid-template-columns:1fr}.operations{align-items:flex-start;flex-direction:column;gap:1rem}}</style>
